  function start(n){
    level=n||progress.level;state='playing';modal=null;mode=null;multiplier=1;reviveUsed=false;refreshUsed=false;clearUses=1;refreshUses=1;moving=[];cars=[];slots=[];toast('');rewardedThisLevel=false;
    M3.Board.init(level);
    // Offline-validated colour/capacity queues. Larger batches deliberately
    // span several exposed regions, so parked cars can require another colour
    // to clear the route. Passenger routing and available bays stay unchanged.
    var plan=strategyPlans[Math.min(Math.max(level-1,0),99)],laneCount=level>=3?5:4;
    for(var i=0;i<plan.length;i++){
      var p=plan[i];
      cars.push({id:i,color:p[0],capacity:p[1],remaining:p[1],column:p[2],stage:'queue',x:0,y:0,targetX:null,targetY:null,shiftDelay:0,shiftMoving:false});
    }
    for(i=0;i<laneCount+1;i++)slots.push({car:null,unlocked:i<laneCount});
    layoutCars(true);last=M3._now();
  }
  function layoutCars(initial){
    var laneCount=level>=3?5:4,rows=[];
    for(var q=0;q<laneCount;q++)rows[q]=0;
    for(var i=0;i<cars.length;i++){
      var c=cars[i];if(c.stage!=='queue')continue;
      var oldRow=c.row;
      c.row=rows[c.column]++;
      var targetOpacity=c.row===0?1:0.25;
      if(initial||c.numberOpacity===undefined)c.numberOpacity=targetOpacity;
      if(c.numberOpacityTarget!==targetOpacity){
        c.numberFadeFrom=c.numberOpacity;c.numberFadeElapsed=0;c.numberOpacityTarget=targetOpacity;
      }
      var tx=L.queueX(c.column,laneCount),ty=L.carY+c.row*L.queuePitch;
      if(initial||typeof c.x!=='number'||c.x===0){c.x=tx;c.y=ty;c.targetX=null;c.targetY=null;c.shiftDelay=0;c.shiftMoving=false;continue;}
      if(Math.abs(c.x-tx)>0.1||Math.abs(c.y-ty)>0.1){
        c.fromQueueX=c.x;c.fromQueueY=c.y;c.targetX=tx;c.targetY=ty;c.shiftElapsed=0;
        // Every visible queue promotion uses the same upward movement.
        c.shiftDelay=(oldRow>=1&&c.row===oldRow-1)?0:260+c.row*65;
        c.shiftMoving=true;
      }
    }
  }
  // Refresh tool effect: shuffle the waiting queue (ids stay in sync with
  // their array slots) so the visible front rows change.
  function reshuffleQueue(){
    var idx=[];
    for(var i=0;i<cars.length;i++)if(cars[i].stage==='queue')idx.push(i);
    for(var k=idx.length-1;k>0;k--){
      var r=Math.floor(Math.random()*(k+1));
      var a=idx[k],b=idx[r];
      if(a===b)continue;
      var ca=cars[a],cb=cars[b];
      var oldColumn=ca.column;ca.column=cb.column;cb.column=oldColumn;
      cars[a]=cb;cars[b]=ca;
      ca.id=b;cb.id=a;
    }
    layoutCars();
  }
  function reward(fn,badge){
    if(state==='ad')return;
    function grant(){fn();if(badge!==undefined){if(!progress.adBadges)progress.adBadges={};progress.adBadges[badge]=true;}save();}
    // Web preview has no ad SDK; grant the reward directly so the whole
    // flow stays testable in a browser. Kwai still watches the ad.
    if(typeof ks==='undefined'){grant();return;}
    var previous=state;state='ad';rewardedThisLevel=true;
    window.KwaiAd.showRewarded(function(){lastAdClosedAt=M3._now();state=previous;grant();},function(){lastAdClosedAt=M3._now();state=previous;toast('广告未完成，奖励未发放');M3.Sound.play('popupFail');});
  }
  function activate(id){
    if(state!=='playing'||modal)return false;
    var c=cars[id];if(!c||c.stage!=='queue')return false;
    var target=-1,nearest=Infinity;
    for(var i=0;i<slots.length;i++){
      if(!slots[i].unlocked||slots[i].car)continue;
      var distance=Math.abs(L.slotX(i,slots.length-1)+26-(c.x+25.85));
      if(distance<nearest){nearest=distance;target=i;}
    }
    if(target<0){c.rejectPulse=320;haptic('blocked');M3.Sound.play('error');return false;}
    if(c.shiftMoving||c.shiftDelay>0||(c.row!==0&&mode!=='refresh')){
      c.rejectPulse=320;
      return false;
    }
    if(mode==='refresh'){
      if(refreshUses<=0){mode=null;return false;}
      refreshUses--;refreshUsed=true;mode=null;toast('');
    }
    M3.Sound.play('carStart');
    c.tapPulse=260;
    slots[target].car=c;c.slot=target;c.stage='entering';c.fromX=c.x;c.fromY=c.y;c.elapsed=0;c.door=0;
    c.route=M3.Motion.entry(c.x+25.85,c.y+38.775,L.slotX(target,slots.length-1)+26,L.bayY+30);
    c.duration=Math.max(820,c.route.length/205*1000);c.angle=0;
    layoutCars();return true;
  }
  function shortenPath(path,person){
    var people=M3.Board.getPeople(),size=M3.Board.getSize();
    var cw=L.boardW/size.cols,ch=L.boardH/size.rows;
    function clear(a,b){
      if(b.y<a.y)return false;
      var dx=b.x-a.x,dy=b.y-a.y;
      // Swept clearance includes the walking head, not just its center.
      for(var j=0;j<people.length;j++){
        var p=people[j];if(p===person||p.gone||(p.reserved&&(p.vacated||p.color===person.color)))continue;
        var center=point(p),lo=0,hi=1;
        var origins=[a.x,a.y],deltas=[dx,dy],centers=[center.x,center.y],radii=[cw*0.9,ch*0.9];
        for(var axis=0;axis<2;axis++){
          var d=deltas[axis],offset=centers[axis]-origins[axis],r=radii[axis];
          if(Math.abs(d)<0.0001){if(Math.abs(offset)>r){hi=-1;break;}}
          else{var t1=(offset-r)/d,t2=(offset+r)/d;lo=Math.max(lo,Math.min(t1,t2));hi=Math.min(hi,Math.max(t1,t2));}
        }
        if(lo<=hi)return false;
      }
      // Eligibility was checked inside the board; departure can cross clear space.
      return true;
    }
    var result=[path[0]],at=0;
    while(at<path.length-1){
      var next=path.length-1;
      while(next>at+1&&!clear(path[at],path[next]))next--;
      result.push(path[next]);at=next;
    }
    return result;
  }
  function boardingCandidates(color,slot,slotLast){
    var people=M3.Board.getPeople(),reach=M3.Board.paths(color),front=M3.Board.frontier(color),list=[];
    for(var i=0;i<people.length;i++){
      var p=people[i];if(p.gone||p.reserved||p.color!==color||!front[i]||reach.dist[i]<0)continue;
      list.push({p:p,cost:reach.dist[i]+Math.abs(point(p).x-(L.slotX(slot,slotLast)+26))/16});
    }
    list.sort(function(a,b){return a.cost-b.cost||a.p.id-b.p.id;});
    return list;
  }
  function schedule(){
    var people=M3.Board.getPeople();
    // First-stopped-first-served: only the earliest parked car that can still
    // take passengers picks beads this round; a later same-colour car never
    // steals its beads just because it parks closer to them.
    var queue=[];
    for(var s=0;s<slots.length;s++){
      var car=slots[s].car;if(!car||(car.stage!=='parked'&&car.stage!=='opening'))continue;
      var occupied=0;for(var a=0;a<moving.length;a++)if(moving[a].car===car)occupied++;
      // Reserve the whole available batch, up to this car's remaining seats.
      if(occupied>=car.remaining)continue;
      queue.push({car:car,slot:s,at:car.parkedAt||0});
    }
    queue.sort(function(a,b){return a.at-b.at;});
    var best=null;
    for(var qi=0;qi<queue.length&&!best;qi++){
      var cur=queue[qi],cands=boardingCandidates(cur.car.color,cur.slot,slots.length-1);
      if(cands.length)best={person:cands[0].p,car:cur.car,cost:cands[0].cost};
    }
    if(!best)return false;
    var pathMap=M3.Board.paths(best.car.color,best.person.id),current=best.person.id;
    var path=[];
    while(current>=0){path.push(point(people[current]));current=pathMap.parent[current];}
    // Start at the passenger and follow the empty route down to the exit.
    var bayLeft=L.slotX(best.car.slot,slots.length-1);
    // The boarding point is the rear hatch, centered above the parked car.
    // The car owns the pixels inside its body, so a passenger never walks over
    // the roof. The exit sits at the board's bottom edge — a hardcoded y once
    // sat above the bottom rows of 66-row levels and people walked back up
    // through standing beads to reach it.
    path.push({x:path[path.length-1].x,y:L.boardY+L.boardH});
    path.push({x:bayLeft+26,y:L.bayY-5});
    path=shortenPath(path,best.person);
    var total=0;for(var pi=1;pi<path.length;pi++){var dx=path[pi].x-path[pi-1].x,dy=path[pi].y-path[pi-1].y;total+=Math.sqrt(dx*dx+dy*dy);}
    best.person.reserved=true;best.person.vacated=false;moving.push({person:best.person,car:best.car,path:path,step:0,t:0,elapsed:0,totalLength:total,x:path[0].x,y:path[0].y});return true;
  }
  function update(dt){
    if(state!=='ad')ensureAdPolicy().playMs+=Math.min(dt,50);
    if(state!=='playing'||modal)return;
    // Speed is the single source of truth: 10 points = 1x, 20 points = 2x.
    dt=Math.min(dt,50)*progress.speed/10*multiplier;
    var i,c,p,pulses=['tapPulse','rejectPulse','parkPulse','shiftPulse','fullPulse'];
    for(i=0;i<slots.length;i++){
      if(slots[i].unlockPulse>0)slots[i].unlockPulse=Math.max(0,slots[i].unlockPulse-dt);
    }
    for(i=0;i<cars.length;i++){
      c=cars[i];
      if(c.numberFadeElapsed<420){
        c.numberFadeElapsed=Math.min(420,c.numberFadeElapsed+dt);
        var fadeT=c.numberFadeElapsed/420,fadeEase=fadeT*fadeT*(3-2*fadeT);
        c.numberOpacity=c.numberFadeFrom+(c.numberOpacityTarget-c.numberFadeFrom)*fadeEase;
      }
      for(var pi=0;pi<pulses.length;pi++)if(c[pulses[pi]]>0)c[pulses[pi]]=Math.max(0,c[pulses[pi]]-dt);
      if(c.numberPulse>0)c.numberPulse=Math.max(0,c.numberPulse-dt);
      if(c.exhaust){for(var ei=c.exhaust.length-1;ei>=0;ei--){var puff=c.exhaust[ei];puff.age+=dt;puff.x+=puff.vx*dt/1000;puff.y+=puff.vy*dt/1000;if(puff.age>=600)c.exhaust.splice(ei,1);}}
      if(c.stage==='queue'&&c.shiftMoving){
        if(c.shiftDelay>0){c.shiftDelay=Math.max(0,c.shiftDelay-dt);continue;}
        c.shiftElapsed+=dt;
        var shiftT=Math.min(1,c.shiftElapsed/420),smooth=shiftT*shiftT*(3-2*shiftT);
        c.x=c.fromQueueX+(c.targetX-c.fromQueueX)*smooth;c.y=c.fromQueueY+(c.targetY-c.fromQueueY)*smooth;
        if(shiftT===1){c.x=c.targetX;c.y=c.targetY;c.targetX=null;c.targetY=null;c.shiftMoving=false;c.shiftPulse=280;}
      }else if(c.stage==='entering'||c.stage==='leaving'){
        var reversing=c.stage==='entering';c.elapsed+=dt;
        var pose=M3.Motion.sample(c.route,c.elapsed,c.duration,reversing);
        c.x=pose.x-25.85;c.y=pose.y-38.775;c.angle=pose.angle;
        if(!reversing){
          c.exhaustClock=(c.exhaustClock||0)+dt;if(!c.exhaust)c.exhaust=[];
          if(c.exhaustClock>=65){c.exhaustClock%=65;var sine=Math.sin(c.angle),cosine=Math.cos(c.angle);c.exhaust.push({x:c.x+25.85+sine*36,y:c.y+38.775-cosine*36,vx:sine*18,vy:-cosine*18,age:0});}
        }
        if(pose.done){
          if(reversing){c.stage='opening';c.elapsed=0;c.angle=0;c.parkPulse=380;c.parkedAt=M3._now();}
          else{c.stage='done';slots[c.slot].car=null;}
        }
      }else if(c.stage==='opening'){
        c.elapsed+=dt;c.door=Math.min(1,c.elapsed/320);
        if(c.door===1){
          c.stage='parked';
        }
      }else if(c.stage==='full'){
        c.elapsed+=dt;
        if(c.elapsed>=720){c.stage='starting';c.elapsed=0;}
      }else if(c.stage==='closing'){
        c.elapsed+=dt;c.door=Math.max(0,1-c.elapsed/320);
        if(c.door===0){c.stage='starting';c.elapsed=0;}
      }else if(c.stage==='starting'){
        c.elapsed+=dt;
        if(c.elapsed>=260){c.stage='leaving';c.elapsed=0;c.route=M3.Motion.exit(c.x+25.85,c.y+38.775,c.slot<(slots.length-1)/2);c.duration=Math.max(760,c.route.length/225*1000);}
      }
    }
    for(i=moving.length-1;i>=0;i--){
      p=moving[i];
      p.elapsed+=dt;
      if(!p.person.vacated){
        var origin=point(p.person),boardSize=M3.Board.getSize(),crowdGrid=L.crowd(boardSize.cols,boardSize.rows);
        // Keep the origin blocked until the walking head has cleared one grid cell.
        if(Math.abs(p.x-origin.x)>=crowdGrid.cellW||Math.abs(p.y-origin.y)>=crowdGrid.cellH)p.person.vacated=true;
      }
      if(p.boarding!==undefined){
        p.boarding+=dt;
        if(p.boarding>=160){
          haptic('board');M3.Board.remove(p.person.id);p.car.remaining--;p.car.numberPulse=280;
          if(!p.car.remaining){p.car.stage='full';p.car.elapsed=0;p.car.door=0;p.car.fullPulse=600;}
          moving.splice(i,1);
        }
        continue;
      }
      p.routeCheck=(p.routeCheck||0)+dt;
      if(p.routeCheck>=80&&p.path.length-p.step>2){
        p.routeCheck=0;
        // Recheck from the current position as the crowd clears, not only at departure.
        var remainingPath=[{x:p.x,y:p.y}].concat(p.path.slice(p.step+1));
        var shorter=shortenPath(remainingPath,p.person);
        if(shorter.length<remainingPath.length){p.path=shorter;p.step=0;p.t=0;}
      }
      var from=p.path[p.step],to=p.path[p.step+1];
      var segmentDx=to.x-from.x,segmentDy=to.y-from.y,segmentLength=Math.sqrt(segmentDx*segmentDx+segmentDy*segmentDy);
      p.t+=dt/(Math.max(1,segmentLength)/74*1000);
      if(p.t>=1){p.step++;p.t=0;if(p.step>=p.path.length-1){p.x=to.x;p.y=to.y;p.boarding=0;continue;}from=p.path[p.step];to=p.path[p.step+1];}
      p.x=from.x+(to.x-from.x)*p.t;p.y=from.y+(to.y-from.y)*p.t;
    }
    // Fill every open car's allowance on the frame its open sprite appears.
    while(schedule()){}
    var transit=moving.length>0;
    for(i=0;i<cars.length;i++)if(cars[i].stage==='entering'||cars[i].stage==='leaving'||cars[i].stage==='opening'||cars[i].stage==='full'||cars[i].stage==='closing'||cars[i].stage==='starting'||cars[i].shiftMoving)transit=true;
    if(!M3.Board.remaining()&&!transit){
      state='won';ensureAdPolicy().finished++;
      var winLevel=level;
      if(progress.completed.indexOf(winLevel)<0)progress.completed.push(winLevel);
      progress.level=winLevel+1;save();
      // Priority 1: interstitial between the victory animation and the
      // settlement screen — never after the player can tap "next level".
      runInterstitial(function(){M3.Sound.play('win');modal='win';});
    }
    else if(!transit&&M3._now()-lastSchedule>=120){
      // Idle boards re-run the passenger scheduler every frame; each run
      // walks a full-board BFS per candidate, so throttling keeps late
      // levels with thousands of beads from stalling the frame loop.
      lastSchedule=M3._now();
      var full=true;for(i=0;i<slots.length;i++)if(slots[i].unlocked&&!slots[i].car)full=false;
      if(full&&!schedule()){
        state='stuck';
        if(reviveUsed){
          // Priority 2: level truly over. Interstitial runs at the final
          // settlement transition — never on the revive-decline tap itself.
          ensureAdPolicy().finished++;save();
          runInterstitial(function(){modal='loss';haptic('fail');M3.Sound.play('lose');});
        }else{modal='revive';M3.Sound.play('fail');}
      }
    }
  }
  function removeCar(c){
    var people=M3.Board.getPeople(),i,left=c.remaining;
    for(i=moving.length-1;i>=0;i--)if(moving[i].car===c){moving[i].person.reserved=false;moving.splice(i,1);}
    for(i=0;i<people.length&&left>0;i++)if(!people[i].gone&&!people[i].reserved&&people[i].color===c.color){M3.Board.remove(i);left--;}
    if(left)throw new Error('车辆颜色容量不守恒');
    c.remaining=0;c.stage='done';if(c.slot!==undefined)slots[c.slot].car=null;
  }
  function clear(id){var c=cars[id];if(!c||c.stage!=='parked'||!clearUses)return;clearUses--;mode=null;
    removeCar(c);layoutCars();state='playing';modal=null;toast('已清除一辆车');
  }
  // The clear tool no longer asks which car: it always removes the leftmost
  // parked vehicle (lowest slot index) in one step.
  function clearLeftmost(){
    for(var s=0;s<slots.length;s++){
      var car=slots[s].car;
      if(car&&car.stage==='parked'){clear(car.id);return true;}
    }
    toast('没有可清除的车辆');return false;
  }
  function completedCount(){
    var unique={};
    (progress.completed||[]).forEach(function(n){if(Number.isInteger(n)&&n>=1&&n<=600)unique[n]=true;});
    return Object.keys(unique).length;
  }
  function albumState(){
    var completed=Math.min(600,completedCount());
    var index=completed>=600?5:Math.floor(completed/100);
    return {completed:completed,index:index,unlocked:index+1,progress:completed>=600?100:completed%100,total:6,cycle:100};
  }
  M3.Game={
    init:function(){var stored=window.KwaiStorage.get('bead-bus-progress');if(stored&&typeof stored.level==='number'&&stored.settings&&stored.completed)progress=stored;progress.themes=progress.themes||{road2Unlocked:false,selected:'road'};if(progress.themes.selected!=='road2')progress.themes.selected='road';level=progress.level;M3.Board.init(progress.level);
    maybeDaily();
    if(window.KwaiBase&&window.KwaiBase.onShow){
      window.KwaiBase.onShow(maybeDaily);
      // Returning to the foreground resumes the bgm (the container pauses
      // audio while backgrounded) unless the music switch is off.
      window.KwaiBase.onShow(function(){if(window.KwaiMedia&&progress.settings[2]!==false)KwaiMedia.Audio.resumeBgm();});
    }
    if(window.KwaiMedia){KwaiMedia.Audio.setSfxEnabled(progress.settings[0]!==false);KwaiMedia.Audio.setBgmEnabled(progress.settings[2]!==false);if(progress.settings[2]!==false)KwaiMedia.Audio.playBgm('audio/bgm.mp3');}},
    start:start,update:update,activate:activate,clear:clear,point:point,
    getState:function(){return state;},getModal:function(){return modal;},getLevel:function(){return level;},getProgress:function(){return progress;},getStatus:function(){if(statusAt&&M3._now()-statusAt>3000)return '';return status;},
    getAlbumState:albumState,
    getArtworkProgress:function(){return albumState().progress*2;},
    getSlots:function(){return slots;},getCars:function(){return cars;},getMoving:function(){return moving;},getMode:function(){return mode;},
    open:function(name){modal=name;collectionPage=1;worksScroll=0;privacyScroll=0;toast('');},close:function(){
      if(modal==='revive'){
        // Declining the revive is its own decision; the interstitial check
        // happens here at the final-settlement transition, not on the tap.
        ensureAdPolicy().finished++;save();
        runInterstitial(function(){modal='loss';haptic('fail');M3.Sound.play('lose');});
        return;
      }
      modal=null;toast('');
    },
    getCollectionPage:function(){return collectionPage;},
    getWorksScroll:function(){return worksScroll;},
    scrollWorks:function(delta){worksScroll=Math.max(0,Math.min(533,worksScroll+delta));},
    setPrivacyHeight:function(h){privacyMax=Math.max(0,h-379);privacyScroll=Math.min(privacyScroll,privacyMax);},
    getPrivacyScroll:function(){return privacyScroll;},
    scrollPrivacy:function(delta){privacyScroll=Math.max(0,Math.min(privacyMax,privacyScroll+delta));},
    previousPage:function(){collectionPage=Math.max(1,collectionPage-1);},
    nextPage:function(){collectionPage=Math.min(modal==='works'?20:1,collectionPage+1);worksScroll=0;},
    refreshReward:function(){reward(function(){refreshUses++;mode='refresh';modal=null;},2);},
    dailyReward:function(){var today=new Date().toDateString();if(progress.dailyClaim===today){toast('今日已领取');return;}reward(function(){clearUses++;refreshUses++;progress.dailyClaim=today;modal=null;});},
    skip:function(){reward(function(){progress.level=Math.max(progress.level,level+1);start(level+1);});},
    toolStock:function(i){return i===1?clearUses:(i===2?refreshUses:0);},
    share:function(){
      if(!window.KwaiShare){toast('请使用快手的分享入口分享游戏');return;}
      // kwai-share.js takes success/fail callbacks (not onSuccess/onFail).
      KwaiShare.share({
        title:'我在「拼豆车站」通过了第'+level+'关，快来挑战我！',
        extraQuery:{level:level,from:'share'},
        success:function(){toast('分享成功');},
        fail:function(){toast('分享未完成');}
      });
    },
    addDesktop:function(){
      if(!window.KwaiShortcut){toast('当前环境不支持添加到桌面');return;}
      toast('');
      KwaiShortcut.add({
        onSuccess:function(){toast('已添加到桌面');},
        onFail:function(err){toast(err&&err.code===-10005?'当前设备不支持添加到桌面':'添加桌面失败，请稍后再试');}
      });
    },
    selectRoad:function(){
      progress.themes=progress.themes||{road2Unlocked:false,selected:'road'};
      progress.themes.selected='road';toast('当前使用经典公路');modal=null;save();
    },
    selectBeach:function(){
      progress.themes=progress.themes||{road2Unlocked:false,selected:'road'};
      if(progress.themes.road2Unlocked){progress.themes.selected='road2';toast('当前使用夏日沙滩');modal=null;save();return;}
      reward(function(){progress.themes.road2Unlocked=true;progress.themes.selected='road2';toast('已解锁并使用夏日沙滩');modal=null;},'road2');
    },
    home:function(){state='home';modal=null;},restart:function(){start(level);},
    toggle:function(i){progress.settings[i]=!progress.settings[i];save();
      if(window.KwaiMedia){if(i===0)KwaiMedia.Audio.setSfxEnabled(progress.settings[0]!==false);if(i===2)KwaiMedia.Audio.setBgmEnabled(progress.settings[2]!==false);}},
    tool:function(i){toast('');if(i===0)modal='upgrade';if(i===1){
      var anyParked=false;for(var s=0;s<slots.length;s++){var pc=slots[s].car;if(pc&&pc.stage==='parked'){anyParked=true;break;}}
      if(!anyParked)toast('没有可清除的车辆');
      else if(clearUses)clearLeftmost();
      else reward(function(){clearUses++;clearLeftmost();},1);
    }if(i===2){if(refreshUses){mode='refresh';modal=null;}else modal='refresh';}if(i===3)modal='shop';},
    upgrade:function(){
      if(progress.speed>=20)return;
      reward(function(){progress.speed=Math.min(20,progress.speed+1);modal=null;},0);
    },
    getMultiplier:function(){return multiplier;},
    doubleSpeed:function(){if(multiplier>1)return;reward(function(){multiplier=2;toast('本局速度×2');});},
    unlockAdSlot:function(index){
      if(state!=='playing'||modal)return false;
      // Callers without an index unlock the first remaining locked bay.
      if(index===undefined){for(index=0;index<slots.length&&slots[index].unlocked;index++){}}
      var target=slots[index];
      if(!target||target.unlocked)return false;
      reward(function(){if(slots[index]===target){target.unlocked=true;target.unlockPulse=420;}});
      return true;
    },
    next:function(){start(progress.level);},
    revive:function(){
      if(reviveUsed||state!=='stuck'||modal!=='revive')return;
      reward(function(){
        // Clear the first three parked bays (leftmost); removeCar also trims
        // each car's colour from the board's upper half to keep solvable.
        var removed=0;
        for(var s=0;s<slots.length&&removed<3;s++){
          var car=slots[s].car;
          if(!car)continue;
          removeCar(car);removed++;
        }
        reviveUsed=true;layoutCars();state='playing';modal=null;toast('已复活');
      });
    },
    getReviveUsed:function(){return reviveUsed;}
  };
